local ColdFrameMaker = {}
local PRODUCTS = {
    iron_coldframe = { name = "Železni hladni okvir", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni hladni okvir za vrtnarje." },
    bronze_coldframe = { name = "Bronast hladni okvir", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast hladni okvir za vrtnarje." },
    silver_coldframe = { name = "Srebrn hladni okvir", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn hladni okvir za vrtnarje." },
    gilded_coldframe = { name = "Pozlačen hladni okvir", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen hladni okvir za vrtnarje." },
    jewel_set_coldframe = { name = "Draguljast hladni okvir", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast hladni okvir za vrtnarje." },
    royal_sovereign_coldframe = { name = "Kraljevski suveren hladni okvir", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren hladni okvir z biseri za krono." },
}
local BUILDINGS = {
    coldframe_workshop = { name = "Coldframe delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    coldframe_house = { name = "Coldframe hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_coldframe_atelier = { name = "Mojstrski coldframe atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_coldframe_palace = { name = "Suverena coldframe palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ColdFrameMaker.ironStock=14; ColdFrameMaker.bronzeStock=12; ColdFrameMaker.woodStock=16; ColdFrameMaker.leatherStock=8; ColdFrameMaker.silverStock=8; ColdFrameMaker.goldStock=6; ColdFrameMaker.jewelStock=4; ColdFrameMaker.pearlStock=4
ColdFrameMaker.productStock = {}; ColdFrameMaker.buildings = {}; ColdFrameMaker.maker = nil; ColdFrameMaker.activeMaking = {}; ColdFrameMaker.totalProducts = 0; ColdFrameMaker.dayTimer = 0
function ColdFrameMaker.init() ColdFrameMaker.ironStock=14; ColdFrameMaker.bronzeStock=12; ColdFrameMaker.woodStock=16; ColdFrameMaker.leatherStock=8; ColdFrameMaker.silverStock=8; ColdFrameMaker.goldStock=6; ColdFrameMaker.jewelStock=4; ColdFrameMaker.pearlStock=4; ColdFrameMaker.productStock={}; ColdFrameMaker.buildings={}; ColdFrameMaker.maker=nil; ColdFrameMaker.activeMaking={}; ColdFrameMaker.totalProducts=0; ColdFrameMaker.dayTimer=0; print("[ColdFrameMaker] Royal Cold Frame Maker System initialized (6 products, 4 buildings)") end
function ColdFrameMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ColdFrameMaker.maker={name=n or ("Okvirjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okvirjar najet: %s (spretnost: %d)",ColdFrameMaker.maker.name,s),"success") end; return true end
function ColdFrameMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ColdFrameMaker.build(id) local ok,e=ColdFrameMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ColdFrameMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ColdFrameMaker.getQualityBonus() local b=0; for _,bd in ipairs(ColdFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ColdFrameMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ColdFrameMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ColdFrameMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ColdFrameMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ColdFrameMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ColdFrameMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ColdFrameMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ColdFrameMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ColdFrameMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ColdFrameMaker.buildings==0 then return false,"Potrebna okvirna delavnica" end; if not ColdFrameMaker.maker then return false,"Potreben okvirjar" end; return true end
function ColdFrameMaker.make(pt,qty) qty=qty or 1; local ok,e=ColdFrameMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ColdFrameMaker.ironStock=ColdFrameMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ColdFrameMaker.bronzeStock=ColdFrameMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ColdFrameMaker.woodStock=ColdFrameMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ColdFrameMaker.leatherStock=ColdFrameMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ColdFrameMaker.silverStock=ColdFrameMaker.silverStock-d.silverCost*qty end; if d.goldCost then ColdFrameMaker.goldStock=ColdFrameMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ColdFrameMaker.jewelStock=ColdFrameMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ColdFrameMaker.pearlStock=ColdFrameMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ColdFrameMaker.maker then t=math.max(1,t-math.floor(ColdFrameMaker.maker.skill/13)) end; table.insert(ColdFrameMaker.activeMaking,{id="coldframe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ColdFrameMaker.completeMaking(m) local q=1.0+(ColdFrameMaker.getQualityBonus()/100); if ColdFrameMaker.maker then q=q+(ColdFrameMaker.maker.skill/140) end; q=math.min(2.5,q); ColdFrameMaker.productStock[m.productType]=(ColdFrameMaker.productStock[m.productType] or 0)+m.quantity; ColdFrameMaker.totalProducts=ColdFrameMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ColdFrameMaker.maker then ColdFrameMaker.maker.itemsMade=ColdFrameMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ColdFrameMaker.maker.skill=math.min(100,ColdFrameMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okvir izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coldframe.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ColdFrameMaker.update(dt) if not _G.state then return end; ColdFrameMaker.dayTimer=ColdFrameMaker.dayTimer+dt; if ColdFrameMaker.dayTimer>=30 then ColdFrameMaker.dayTimer=0; for i=#ColdFrameMaker.activeMaking,1,-1 do local m=ColdFrameMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ColdFrameMaker.completeMaking(m); table.remove(ColdFrameMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ColdFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ColdFrameMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ColdFrameMaker.getStats() return {ironStock=ColdFrameMaker.ironStock,bronzeStock=ColdFrameMaker.bronzeStock,woodStock=ColdFrameMaker.woodStock,leatherStock=ColdFrameMaker.leatherStock,silverStock=ColdFrameMaker.silverStock,goldStock=ColdFrameMaker.goldStock,jewelStock=ColdFrameMaker.jewelStock,pearlStock=ColdFrameMaker.pearlStock,productStock=ColdFrameMaker.productStock,numBuildings=#ColdFrameMaker.buildings,hasMaker=ColdFrameMaker.maker~=nil,makerName=ColdFrameMaker.maker and ColdFrameMaker.maker.name or "—",makerSkill=ColdFrameMaker.maker and ColdFrameMaker.maker.skill or 0,activeMaking=#ColdFrameMaker.activeMaking,totalProducts=ColdFrameMaker.totalProducts} end
return ColdFrameMaker
